-- 0003_add_org_client — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- client: top of the SOP-DEL-02 §3 hierarchy (E1 AC1). The row is the tenant itself, so its id is the
-- client id other tables carry. Staff see all clients; a client user sees only its own client; partners
-- see nothing until a policy links them to their assigned jobs or sites.
CREATE TABLE client (
  id          uuid PRIMARY KEY,
  -- First segment of the Project ID: up to 8 letters A–Z (rule org/client-short-code). Never reused.
  short_code  text NOT NULL UNIQUE,
  name        text NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz
);

ALTER TABLE client ENABLE ROW LEVEL SECURITY;
CREATE POLICY client_internal ON client FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY client_own_read ON client FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND id = ANY (app.client_ids()));
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON client TO ocs_app;
